
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_xlyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_xlyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.394988337138090e+00, -4.313243789502623e+00, -4.198782176284003e+00, -4.040394810593869e+00, -3.824923518965349e+00, -3.538864646001828e+00, -3.172096728824780e+00, -2.724399847616560e+00, -2.213326573323817e+00, -1.674039889833711e+00, -1.132112556218701e+00, -7.452853502767568e-01, -6.379385130554772e-01, -5.340603344527125e-01, -3.923779829912961e-01, -2.513462306909537e-01, -1.461458417931648e-01, -7.619116717774238e-02, -4.379596878492467e-02, -3.007729214338967e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


